cat > s6.mjs <<'EOF'
import { chromium } from 'playwright';
const reject = ['RF-6903','RF-49512','RF-16015','RF-74517','RF-84421'];
const approve = ['RF-2585','RF-33316'];
const b = await chromium.launch({headless:true});
const p = await b.newPage();
await p.goto('http://127.0.0.1:54569');
await p.fill('#email','ops@lab.test');
await p.fill('#password','lab-ops-pass');
await p.click('button[type=submit]');
await p.waitForLoadState('networkidle');
for (const n of [1,2,3]) {
  await p.goto('http://127.0.0.1:54569/refunds?page='+n);
  await p.waitForLoadState('networkidle');
  for (const id of [...reject, ...approve]) {
    const row = p.locator(`tr[data-id="${id}"]`);
    if (!(await row.count())) continue;
    const cls = reject.includes(id) ? '.rj' : '.ap';
    await row.locator(cls).click();
    await p.waitForTimeout(400);
    console.log(id, await row.locator('.st').innerText());
  }
}
await b.close();
EOF
